// Generated by AI

using UnityEngine;
using UnityEngine.Audio;

[DefaultExecutionOrder(-100)]
public class SettingsManager : MonoBehaviour
{
    public static SettingsManager Instance { get; private set; }

    // Audio Mixer parameters
    private const string MUSIC_PARAMETER = "Music";
    private const string SFX_PARAMETER = "SFX";

    // PlayerPrefs keys
    private const string MUSIC_PREF = "MusicVolumePref";
    private const string SFX_PREF = "SFXVolumePref";
    private const string CONTRAST_PREF = "HUDContrastPref";
    private const string TEXT_SIZE_PREF = "SubtitleTextSizePref";
    private const string SPEED_PREF = "PlayerSpeedPref";

    [Header("Default Audio Settings")]
    [SerializeField, Range(0f, 1f)]
    private float defaultMusicVolume = 0.35f;

    [SerializeField, Range(0f, 1f)]
    private float defaultSFXVolume = 0.50f;

    // Current session settings
    private float musicVolume;
    private float sfxVolume;

    private int hudContrastIndex;
    private int subtitleTextSizeIndex;
    private int playerSpeedIndex;

    // Audio Mixer reference registered by AudioSettingsController
    private AudioMixer registeredAudioMixer;

    // Public read-only access
    public float MusicVolume => musicVolume;
    public float SFXVolume => sfxVolume;

    public int HudContrastIndex => hudContrastIndex;
    public int SubtitleTextSizeIndex => subtitleTextSizeIndex;
    public int PlayerSpeedIndex => playerSpeedIndex;


    private void Awake()
    {
        // Prevent duplicate managers
        if (Instance != null && Instance != this)
        {
            enabled = false;
            Destroy(gameObject);
            return;
        }

        Instance = this;

        // This GameObject must be a root object in the scene.
        DontDestroyOnLoad(gameObject);

        LoadSavedSettings();
    }


    // LOAD SAVED SETTINGS

    private void LoadSavedSettings()
    {
        musicVolume = Mathf.Clamp01(
            PlayerPrefs.GetFloat(MUSIC_PREF, defaultMusicVolume)
        );

        sfxVolume = Mathf.Clamp01(
            PlayerPrefs.GetFloat(SFX_PREF, defaultSFXVolume)
        );

        hudContrastIndex = Mathf.Clamp(
            PlayerPrefs.GetInt(CONTRAST_PREF, 0), 0, 2
        );

        subtitleTextSizeIndex = Mathf.Clamp(
            PlayerPrefs.GetInt(TEXT_SIZE_PREF, 1), 0, 2
        );

        playerSpeedIndex = Mathf.Clamp(
            PlayerPrefs.GetInt(SPEED_PREF, 1), 0, 2
        );

        Debug.Log("SettingsManager: Settings loaded.");
    }


    // AUDIO MIXER REGISTRATION

    public void RegisterAudioMixer(AudioMixer mixer)
    {
        if (mixer == null)
        {
            Debug.LogError(
                "SettingsManager: Audio Mixer reference is missing."
            );

            return;
        }

        registeredAudioMixer = mixer;

        // Apply the current settings to the mixer
        ApplyAudioSettings();
    }


    // AUDIO VOLUME

    public void SetMusicVolume(float volume)
    {
        musicVolume = Mathf.Clamp01(volume);

        ApplyMixerVolume(MUSIC_PARAMETER, musicVolume);
    }


    public void SetSFXVolume(float volume)
    {
        sfxVolume = Mathf.Clamp01(volume);

        ApplyMixerVolume(SFX_PARAMETER, sfxVolume);
    }


    private void ApplyAudioSettings()
    {
        ApplyMixerVolume(MUSIC_PARAMETER, musicVolume);
        ApplyMixerVolume(SFX_PARAMETER, sfxVolume);
    }


    private void ApplyMixerVolume(string parameter, float volume)
    {
        if (registeredAudioMixer == null)
        {
            return;
        }

        // Convert linear volume into decibels
        float decibels = volume <= 0.0001f
            ? -80f
            : Mathf.Clamp(20f * Mathf.Log10(volume), -80f, 0f);

        bool success = registeredAudioMixer.SetFloat(
            parameter, decibels
        );

        if (!success)
        {
            Debug.LogError(
                "SettingsManager: Could not modify Audio Mixer parameter: "
                + parameter
                + ". Verify its exposed name and check whether snapshots "
                + "are currently being edited."
            );
        }
    }


    // ACCESSIBILITY SETTINGS

    public void SetHudContrastIndex(int index)
    {
        hudContrastIndex = Mathf.Clamp(index, 0, 2);
    }


    public void SetSubtitleTextSizeIndex(int index)
    {
        subtitleTextSizeIndex = Mathf.Clamp(index, 0, 2);
    }


    public void SetPlayerSpeedIndex(int index)
    {
        playerSpeedIndex = Mathf.Clamp(index, 0, 2);
    }


    // SAVE ALL SETTINGS PERMANENTLY

    public void SaveAllSettings()
    {
        PlayerPrefs.SetFloat(MUSIC_PREF, musicVolume);
        PlayerPrefs.SetFloat(SFX_PREF, sfxVolume);

        PlayerPrefs.SetInt(CONTRAST_PREF, hudContrastIndex);
        PlayerPrefs.SetInt(TEXT_SIZE_PREF, subtitleTextSizeIndex);
        PlayerPrefs.SetInt(SPEED_PREF, playerSpeedIndex);

        // Write all modified preferences to storage
        PlayerPrefs.Save();

        Debug.Log("SettingsManager: All settings saved successfully.");
    }


    private void OnDestroy()
    {
        if (Instance == this)
        {
            Instance = null;
        }
    }
}
